"""Service-led Proteus homepage. Approved earlier editions remain archived separately."""
from html import escape
from icons import icon


def render_home(image, button, faq, cta, data, arrow, parts):
    def photo(name, alt, cls='', eager=False):
        return f'<img src="/assets/{name}.webp" alt="{escape(alt,quote=True)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async">'

    programmes = data['programmes']
    visual = parts['visual']
    rail = ''.join(f'''<article class="rail-card" data-slide><a href="/{p['slug']}/"><div class="rail-image rail-image-{p['slug']}">{visual(p, rail=True)}<span class="rail-card-index">{i:02d}</span><span class="rail-card-arrow" aria-hidden="true">{icon("arrow-up-right")}</span></div><div class="rail-card-body"><p class="eyebrow">{p['label']}</p><h3>{p['short']}</h3><p>{escape(p['caption'])}</p></div></a></article>''' for i,p in enumerate(programmes,1))
    mosaic_items = [
        ('pa-camp-squad','holiday-programmes','Holiday programmes','mosaic-big'),
        ('pa-floodlights','academy','Floodlit performance training','mosaic-tall'),
        ('pa-preschool','early-years-fundamentals','Little PlayKicks preschools',''),
        ('pa-school-celebrate','school-sports-coaching','School sport',''),
        ('pa-beach','community-organisation','Community events','mosaic-wide'),
        ('pa-workshop','coach-development','Coach education',''),
        ('pa-coach-talk','individual-performance-coaching','1:1 coaching',''),
    ]
    mosaic = ''.join(f'<a class="mosaic-item {cls}" href="/{slug}/">{photo(img, data["images"][img])}<span class="mosaic-caption">{label} {icon("arrow-up-right")}</span></a>' for img,slug,label,cls in mosaic_items)
    record = ''.join(f'<li><span class="tick" aria-hidden="true">{icon("check")}</span>{escape(x)}</li>' for x in data['update2026']['record'][:4])
    quick_links = ''.join(f'<a href="/{p["slug"]}/">{escape(p["title"])} {arrow}</a>' for p in programmes)
    instagram_icon = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="3" y="3" width="18" height="18" rx="5" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="12" cy="12" r="4.2" fill="none" stroke="currentColor" stroke-width="1.7"/><circle cx="17.5" cy="6.7" r="1.1" fill="currentColor"/></svg>'
    instagram_posts = [
        ('ig-hiring','DUR0wjViSjG','Coaching opportunities at Proteus Sports Group'),
        ('training','DPPnMvgk--7','Individual football training with Proteus'),
        ('ig-claudia-alex','DPkJmvYExJB','Meet Proteus coaches Claudia and Alex'),
        ('ig-team-day','DP2NqU4k4BK','The Proteus team connecting with future sports coaches'),
        ('ig-tom-caleb','DMeu8RvpWD_','Meet Proteus coaches Tom and Caleb'),
        ('coaches','DKtZIb4pvYF','Meet Proteus coach Ollie')
    ]
    instagram_tiles = ''.join(f'<a class="instagram-post" href="https://www.instagram.com/p/{post}/" target="_blank" rel="noopener noreferrer" aria-label="{escape(alt,quote=True)} — view on Instagram">{photo(img,alt)}<span class="instagram-post-icon">{instagram_icon}</span><span class="instagram-post-caption">View on Instagram {icon("arrow-up-right")}</span></a>' for img,post,alt in instagram_posts)
    return f'''
    <div id="reading-progress" aria-hidden="true"></div>
    <section class="motion-hero" aria-label="More than a game">
      <div class="hero-court" aria-hidden="true"></div>
      <div class="motion-hero-copy"><p class="eyebrow"><span class="status-dot"></span> CHRISTCHURCH, NZ / SPORTS COACHING</p><h1><span class="hero-line">MORE THAN</span><span class="hero-line hero-line-lime">A GAME.</span></h1><p class="hero-deck">Skills for sport.<br><strong>Confidence for life.</strong></p><p class="hero-description">Nearly 60 coaches. Six sports. Nine programmes.<br>From preschool to retirement villages.</p><div class="button-row">{button('View programmes','#programmes','button-lime')}{button('Get in touch','/contact/','button-outline')}</div><a class="hero-scroll" href="#programmes"><span aria-hidden="true">{icon("arrow-down")}</span> EXPLORE OUR PROGRAMMES</a></div>
      <div class="motion-hero-media"><video id="hero-motion" muted loop playsinline preload="metadata" poster="/assets/motion-poster.webp" aria-hidden="true"><source src="/assets/proteus-motion.mp4" type="video/mp4"></video><div class="hero-video-shade"></div><div class="video-corner"><span class="live-dot"></span> PROTEUS IN MOTION <span>01 / FIELD NOTES</span></div><button class="watch-film" data-open-film type="button" aria-haspopup="dialog"><span class="play-disc" aria-hidden="true">{icon("play")}</span><span>REAL PEOPLE.<br><strong>REAL ENERGY.</strong><small>Watch the camp film {icon("arrow-up-right")}</small></span></button><div class="hero-film-note">PAPANUI REDWOOD / A DAY AT CAMP</div></div>
      <figure class="hero-inset" data-parallax="0.04">{image('early-years')}<figcaption>EVERY START COUNTS. {icon("arrow-up-right")}</figcaption></figure>
    </section>
    <button class="motion-control" id="motion-toggle" type="button" aria-pressed="false"><span data-motion-icon aria-hidden="true">{icon("pause", data_icon="pause")}{icon("play", data_icon="play", hidden=True)}</span> <span data-motion-label>Pause motion</span></button>
    <div class="motion-marquee" aria-label="Simplicity, quality and community"><div class="marquee-track" aria-hidden="true"><span>SIMPLICITY <i>{icon("asterisk")}</i> QUALITY <i>{icon("asterisk")}</i> COMMUNITY <i>{icon("asterisk")}</i> THE PROTEUS WAY <i>{icon("asterisk")}</i></span><span>SIMPLICITY <i>{icon("asterisk")}</i> QUALITY <i>{icon("asterisk")}</i> COMMUNITY <i>{icon("asterisk")}</i> THE PROTEUS WAY <i>{icon("asterisk")}</i></span></div></div>
    {parts['stats_band']()}
    <section class="programme-reel" id="programmes" data-carousel aria-label="Explore Proteus programmes"><div class="container"><div class="reel-heading reveal"><div><p class="eyebrow">OUR PROGRAMMES</p><h2>SPORTS COACHING.<br><span>MADE FOR YOU.</span></h2></div><div class="reel-side"><p>Nine programmes for players, preschools, schools,<br>clubs, coaches and communities.</p><a href="/programmes/" class="text-link">All programmes {arrow}</a></div></div></div><div class="rail-track" data-carousel-track tabindex="0" role="region" aria-label="Swipe through nine programmes">{rail}</div><div class="container carousel-bottom"><span data-carousel-status aria-live="polite">01 / 09</span><div class="carousel-progress" data-carousel-progress aria-hidden="true"></div><div class="carousel-buttons"><button type="button" data-carousel-prev aria-label="Previous programmes">{icon("arrow-left")}</button><button type="button" data-carousel-next aria-label="Next programmes">{icon("arrow-right")}</button></div></div><nav class="container programme-quick-links" aria-label="All programme links">{quick_links}</nav></section>
    <section class="action-mosaic" aria-labelledby="mosaic-heading"><div class="container"><div class="mosaic-head reveal"><div><p class="eyebrow">EVERY WEEK. ACROSS THE CITY.</p><h2 id="mosaic-heading">COACHING<br><span>IN ACTION.</span></h2></div><p>Preschool courts to floodlit pitches, school fields to the beach. This is what a week at Proteus looks like.</p></div><div class="mosaic-grid">{mosaic}</div></div></section>
    <section class="academy-experience" aria-labelledby="academy-heading"><div class="academy-grid-lines" aria-hidden="true"></div><div class="academy-year" data-parallax="0.07" aria-hidden="true">2027</div><div class="container academy-v2-grid"><div class="academy-v2-heading reveal"><p class="eyebrow"><span class="status-dot"></span> THE PROTEUS ACADEMY / 2027 INTAKE</p><h2 id="academy-heading">BRING<br>YOUR<br><span>AMBITION.</span></h2><p>Football + basketball.<br>For the athlete you’re becoming.</p><a href="/academy/" class="text-link">Explore the Academy {arrow}</a></div><div class="academy-v2-detail"><div class="academy-pillars"><article class="reveal"><span>01</span><div><h3>YOUR SKILLS.</h3><p>Technical development.</p></div></article><article class="reveal"><span>02</span><div><h3>YOUR ENGINE.</h3><p>Athletic performance.</p></div></article><article class="reveal"><span>03</span><div><h3>YOUR MINDSET.</h3><p>Performance psychology.</p></div></article><article class="reveal"><span>04</span><div><h3>YOUR UNDERSTANDING.</h3><p>Athlete education.</p></div></article></div><div class="academy-sport-box reveal"><p class="eyebrow">YOUR SPORT. YOUR NEXT STEP.</p><div class="academy-switch" role="group" aria-label="Choose your academy sport"><button data-sport="football" aria-pressed="true" type="button">Football {arrow}</button><button data-sport="basketball" aria-pressed="false" type="button">Basketball {arrow}</button></div><p id="academy-sport-description">Football development. Your next step starts here.</p><a id="academy-sport-link" class="button button-lime" href="/contact/?interest=Academy%20%E2%80%94%20football">Express your interest {arrow}</a><a id="academy-sport-contact" class="academy-contact-link" href="mailto:oliver@proteus.nz">oliver@proteus.nz</a><p class="academy-other-sport">Or <a id="academy-other-sport" href="/contact/?interest=Academy%20%E2%80%94%20basketball"><span data-other-sport-label>enquire about basketball</span> {arrow}</a></p><span class="academy-commitment">Small groups. Individual planning. Regular feedback.<br>Alongside your school and club sport.</span></div></div></div></section>
    <section class="people-editorial"><div class="people-photo">{image('team')}<span class="photo-note">GOOD PEOPLE. GREAT EXPERIENCES.</span></div><div class="people-editorial-copy reveal"><p class="eyebrow">THE PEOPLE IN YOUR CORNER</p><h2>IT STARTS<br>WITH<br><span>PEOPLE.</span></h2><p>Energy. Care. A shared love of sport. Our people bring it to every session, helping players grow and communities connect.</p>{button('Meet the Proteus team','/about/#team','button-primary')}<a class="text-link" href="/contact/?interest=Coaching%20opportunities">Your next step could be coaching {arrow}</a></div></section>
    {parts['partners_wall']()}
    <section class="update-band" aria-labelledby="update-band-heading"><div class="container update-band-grid"><div class="update-band-photo reveal">{photo('pa-club-squad', data['images']['pa-club-squad'])}<span class="photo-note">QUARTER ONE / 2026</span></div><div class="update-band-copy reveal"><p class="eyebrow"><span class="status-dot"></span> 2026 UPDATE</p><h2 id="update-band-heading">A RECORD<br><span>START TO 2026.</span></h2><p>One of the busiest and most exciting starts to a year in Proteus history.</p><ul class="tick-list">{record}</ul>{button('Read the 2026 update','/2026/','button-lime')}</div></div></section>
    <section class="instagram-section" id="instagram" aria-labelledby="instagram-heading"><div class="container"><div class="instagram-heading reveal"><div><p class="eyebrow">COACHING IN ACTION. PEOPLE IN OUR CORNER.</p><h2 id="instagram-heading">FROM OUR<br><span>INSTAGRAM.</span></h2></div><a class="instagram-profile" href="https://www.instagram.com/proteussportsgroup/" target="_blank" rel="noopener noreferrer">{instagram_icon}<span>@proteussportsgroup</span>{arrow}</a></div><div class="instagram-grid"><article class="instagram-reel-card"><header><a href="https://www.instagram.com/proteussportsgroup/" target="_blank" rel="noopener noreferrer">{instagram_icon}<strong>proteussportsgroup</strong></a><span>REEL</span></header><div class="instagram-video-wrap"><video id="instagram-reel" controls muted playsinline preload="metadata" poster="/assets/motion-poster.webp" aria-label="Proteus Instagram reel: football in action at Papanui Redwood camp, silent excerpt"><source src="/assets/proteus-camp-film.mp4" type="video/mp4"></video></div><footer><p>Football, friendships and plenty of play.<br>Papanui Redwood camp.</p><a href="https://www.instagram.com/proteussportsgroup/reel/DayuD8hTQ_A/" target="_blank" rel="noopener noreferrer">View original reel {arrow}</a></footer></article>{instagram_tiles}</div><div class="instagram-section-footer"><p>A look at our coaching, our people and life at Proteus.</p><a class="text-link" href="https://www.instagram.com/proteussportsgroup/" target="_blank" rel="noopener noreferrer">See more on Instagram {arrow}</a></div></div></section>
    <div class="partner-strip"><div class="container"><span>OUR APPAREL PARTNER</span><a href="https://www.dynastysport.co.nz/" target="_blank" rel="noopener noreferrer">Dynasty Sport {arrow}</a></div></div>
    <section class="section faq-section"><div class="container faq-grid"><div class="reveal"><p class="eyebrow">A FEW THINGS TO KNOW</p><h2>GOOD<br><span class="text-purple">QUESTIONS.</span></h2><a class="text-link" href="/contact/">Let’s talk {arrow}</a></div>{faq(3)}</div></section>
    <section class="final-whistle"><div class="container"><p class="eyebrow reveal">YOUR NEXT CHAPTER</p><h2 class="reveal">LET’S<br><span>GET GOING.</span></h2><div class="final-whistle-bottom reveal"><p>A first session. A bigger goal. A new partnership.<br>It starts with a conversation.</p>{button('Talk to our team','/contact/','button-lime')}</div></div><span class="final-court-circle" aria-hidden="true"></span></section>
    <dialog id="film-dialog" class="film-dialog" aria-labelledby="film-title"><div class="film-dialog-panel"><div class="film-dialog-header"><div><p class="eyebrow">PROTEUS / FIELD NOTES</p><h2 id="film-title">A day at camp.</h2></div><button type="button" data-close-film aria-label="Close camp film">{icon("close")}</button></div><video id="film-video" controls muted playsinline preload="none" poster="/assets/motion-poster.webp" aria-label="Silent film of football activities at the Proteus Papanui Redwood camp"><source src="/assets/proteus-camp-film.mp4" type="video/mp4"></video><p class="film-description">Papanui Redwood camp. Football, friendships and plenty of play.<span>Silent film · Proteus Sports Group</span></p></div></dialog>
    <noscript><div class="container no-script-film"><a class="text-link" href="/assets/proteus-camp-film.mp4">Watch the silent camp film {arrow}</a></div></noscript>
    '''
